CREATE TABLE IF NOT EXISTS hyrup_experts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), display_name TEXT NOT NULL, headline TEXT NOT NULL, field TEXT NOT NULL, bio TEXT NOT NULL, skills TEXT[] NOT NULL DEFAULT '{}', years_experience INTEGER NOT NULL DEFAULT 0, hourly_rate NUMERIC, is_verified BOOLEAN NOT NULL DEFAULT FALSE, is_published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());